// Template registry (Day 16, extended Day 30) — pure and client-safe.
//
// A template is a real Office file with real, original content
// (Forma's own — no WPS template, no copied text), committed in
// src/lib/templates/ and generated by scripts/generate-templates.py
// (the script is the source of truth; it also renders the first-page
// thumbnail into public/templates/ and extracts the preview text
// into <slug>.preview.json, so the preview can never drift from
// the file).
//
// This module only lists the templates and their preview data, so
// the gallery page can import it. The file bytes are read by
// src/lib/templates.server.ts (which uses node:fs and must never
// be imported by a client component).
//
// Day 30: the registry now covers three file types (docx, xlsx,
// pptx). The `fileType` field is what the apply action uses for
// the new document's extension and MIME type — the template's own
// type, never a hardcoded "docx".
import proposalPreview from "@/lib/templates/proposal.preview.json";
import invoicePreview from "@/lib/templates/invoice.preview.json";
import minutesPreview from "@/lib/templates/minutes.preview.json";
import certificatePreview from "@/lib/templates/certificate.preview.json";
import budgetPreview from "@/lib/templates/budget.preview.json";
import pitchPreview from "@/lib/templates/pitch.preview.json";
import resumePreview from "@/lib/templates/resume.preview.json";
import letterPreview from "@/lib/templates/letter.preview.json";
import reportPreview from "@/lib/templates/report.preview.json";

export type TemplatePreviewEntry = {
  style: string;
  text: string;
};

export type TemplateFileType = "docx" | "xlsx" | "pptx";

export type Template = {
  id: string;
  name: string;
  description: string;
  category: string;
  fileName: string;
  fileType: TemplateFileType;
  thumbnailPath: string;
  preview: TemplatePreviewEntry[];
};

